action_input.code:
import os
matches=[]
for root,dirs,files in os.walk('.'): 
    for f in files:
        path=os.path.join(root,f)
        try:
            with open(path,'r',encoding='utf-8',errors='ignore') as fh:
                txt=fh.read()
            if 'creatinine' in txt.lower():
                matches.append(path)
        except Exception as e:
            pass
print(matches)

